// BUILD is generated by Vite. Only these public assets and catalog routes are intercepted.
const STATIC = 'pianora-pwa-static-v1';
const CATALOG = 'pianora-pwa-catalog-v1';
const SCORES = 'pianora-pwa-scores-v1';
const bundled = new Set(BUILD.assets);
const catalogList = /^\/api\/catalog\/(?:scores(?:\/[a-z0-9_-]+)?|composers|collections)$/;
const scoreFile = /^\/api\/catalog\/files\/[a-f0-9]{64}\.(?:ly|mid|midi|musicxml|xml|mxl)$/;

function staticKey(path) {
  if (bundled.has(path)) return path;
  const revision = BUILD.runtime[path];
  return revision ? path + '?pwa-rev=' + revision : null;
}
function storable(response) {
  return response.status === 200 && response.type !== 'opaque' && !response.redirected &&
    !response.headers.has('content-range') && !/private|no-store/i.test(response.headers.get('cache-control') || '') &&
    !/text\/html/i.test(response.headers.get('content-type') || '');
}

// Promote only complete releases. The last working offline shell survives a failed install.
self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(STATIC);
    await Promise.all(BUILD.core.map(async path => {
      const key = staticKey(path);
      if (await cache.match(key)) return;
      const response = await fetch(new Request(path, { priority:'low',
        cache:BUILD.runtime[path] ? 'no-cache' : 'default' }));
      if (!storable(response)) throw new Error('Incomplete app shell: '+path);
      await cache.put(key, response);
    }));
    await self.skipWaiting();
  })());
});
self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(STATIC);
    // Older workers served embedded HTML even on reload. Upgrade their already
    // controlled windows once; subsequent releases load directly on navigation.
    const legacyWindows = await cache.match('/') ? [] : await self.clients.matchAll({type:'window'});
    await cache.put('/', new Response(BUILD.html, {headers:{'Content-Type':'text/html; charset=utf-8'}}));
    for (const request of await cache.keys()) {
      const url = new URL(request.url);
      if (url.pathname === '/') continue;
      if (staticKey(url.pathname) !== url.pathname + url.search) await cache.delete(request);
    }
    await self.clients.claim();
    for (const client of legacyWindows) {
      const url = new URL(client.url);
      if (isAppEntry(url)) {
        // A navigation intercepted by this worker can only finish after activation.
        void client.navigate(client.url).catch(() => {});
      }
    }
  })());
});

async function trim(cache, limit) {
  const keys = await cache.keys();
  await Promise.all(keys.slice(0, Math.max(0,keys.length-limit)).map(key => cache.delete(key)));
}
async function write(cache, key, response, limit) {
  await cache.put(key, response);
  if (limit) await trim(cache,limit);
}
async function immutable(event, name, key, limit) {
  let cache;
  try {
    cache = await caches.open(name);
    const hit = await cache.match(key);
    if (hit) return hit;
  } catch { /* Private browsing and storage pressure can disable Cache Storage. */ }
  // Public worklet and impulse-response filenames are stable. A new digest
  // must revalidate the HTTP copy once before populating its new cache key.
  const response = await fetch(event.request, BUILD.runtime[new URL(event.request.url).pathname] ? {cache:'no-cache'} : {});
  if (cache && storable(response)) event.waitUntil(write(cache,key,response.clone(),limit).catch(() => {}));
  return response;
}

async function catalog(event, request) {
  let cache, hit;
  try {
    cache = await caches.open(CATALOG);
    hit = await cache.match(request);
  } catch { /* Online requests still work without disk storage. */ }
  const refresh = async () => {
    const response = await fetch(request);
    if (cache && storable(response) && /application\/json/i.test(response.headers.get('content-type') || ''))
      event.waitUntil(write(cache,request,response.clone(),160).catch(() => {}));
    else if (cache && response.status === 404) event.waitUntil(cache.delete(request).catch(() => {}));
    return response;
  };
  if (!hit) return refresh();
  // Public metadata already has a short freshness window at the edge. Revalidate quietly.
  if (!(Date.now() - Date.parse(hit.headers.get('date') || '') < 60_000)) {
    event.waitUntil(refresh().then(response => response.body?.cancel()).catch(() => {}));
  }
  return hit;
}

function isAppEntry(url) {
  return !url.search && (url.pathname === '/' || url.pathname === '/index.html');
}

async function appDocument(request) {
  // Revalidate the small HTML entry point. Hashed JS, CSS and model packs
  // keep their normal caches, including when the worker update is still installing.
  try {
    const response = await fetch(request, {cache:'no-cache'});
    if (response.status < 500) return response;
  } catch { /* Offline: use the last fully installed release. */ }
  return await (await caches.open(STATIC)).match('/') ??
    new Response(BUILD.html, {headers:{'Content-Type':'text/html; charset=utf-8'}});
}

self.addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin ||
      request.headers.has('authorization') || request.headers.has('range')) return;
  if (request.mode === 'navigate') {
    if (isAppEntry(url)) event.respondWith(appDocument(request));
    return;
  }
  const key = !url.search && staticKey(url.pathname);
  if (key) event.respondWith(immutable(event,STATIC,key));
  else if (!url.search && scoreFile.test(url.pathname)) event.respondWith(immutable(event,SCORES,url.href,64));
  else if (catalogList.test(url.pathname)) event.respondWith(catalog(event,request));
});
